    rv_label: "Testimonianze",
    rv_title: "Cosa dicono i nostri clienti",
    rv_intro: "Parole di clienti reali, raccolte negli anni: lettere, email e recensioni pubbliche.",
    nav_label: "Navigazione",
    nav_products: "Collezioni",
    nav_marine: "Collezioni Yachting",
