    srch_ph: "Cerca prodotti, codici ricambio, pagine",
    srch_quick: "Vai a",
    srch_foot: "Frecce per spostarti, Invio per aprire",
    srch_g_prod: "Prodotti",
    srch_g_cat: "Categorie",
